-- Production RPCs under caller JWTs; fixtures and writes roll back together.
create extension if not exists pgtap;
begin;
select no_plan();
update auth.users set email_confirmed_at = now() where id in ('70000010-0000-4000-8000-000000000010','70000001-0000-4000-8000-000000000001');
update public.users set status = 'active', primary_account_type = null where id = '70000010-0000-4000-8000-000000000010';
insert into public.onboarding_progress(user_id, selected_track) values('70000010-0000-4000-8000-000000000010', 'professional')
on conflict(user_id) do update set selected_track = excluded.selected_track;
insert into public.individual_onboarding(user_id, prof_concrete_type) values('70000010-0000-4000-8000-000000000010', 'engineer')
on conflict(user_id) do update set prof_concrete_type = excluded.prof_concrete_type;
create temp table engineer_test_values(name text primary key, value text);
grant all on engineer_test_values to authenticated;
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.engineer_collections'::regclass,'public.engineer_collection_entries'::regclass,'public.engineer_request_context'::regclass)), 'all personal tables enforce RLS');
select ok(not has_table_privilege('authenticated','public.engineer_collections','insert'), 'no direct collection writes');
select ok(not has_table_privilege('authenticated','public.engineer_request_context','update'), 'no direct retarget writes');
select ok(not has_function_privilege('anon','public.engineer_collection_change(text,uuid,text,text,uuid)','execute'), 'anonymous caller cannot mutate collections');
select ok(not has_table_privilege('authenticated','public.profile_unavailable_periods','insert'), 'unavailable periods have no direct insert');
select ok(not has_table_privilege('authenticated','public.profile_unavailable_periods','delete'), 'unavailable periods have no direct delete');
set local role authenticated;
set local request.jwt.claims = '{"sub":"70000010-0000-4000-8000-000000000010","role":"authenticated"}';
select lives_ok($$select public.set_unavailable_period(current_date, current_date + 3)$$, 'engineer blocks a period through the function');
select lives_ok($$select public.remove_unavailable_period((select id from public.profile_unavailable_periods limit 1))$$, 'and removes it');
select is((select count(*)::integer from public.profile_unavailable_periods), 0, 'the period is gone');
select is(app.viewer_product_audience(null), 'engineer', 'declared engineer can browse the engineer catalog before verification');
select is((select primary_account_type::text from public.users where id=auth.uid()), null, 'buying audience never promotes the canonical persona');
select lives_ok($$insert into engineer_test_values values('team', public.engineer_collection_change('create_team', null, 'Design collaborators')::text)$$, 'declared engineer creates a private team');
select is((select count(*)::integer from public.engineer_collections), 1, 'owner can read their team');
select lives_ok($$select public.engineer_collection_change('save', null, null, 'organization', '9c000000-cccc-4ccc-8ccc-000000000001')$$, 'save a public showroom');
select lives_ok($$select public.engineer_collection_change('save', null, null, 'organization', '9c000000-cccc-4ccc-8ccc-000000000001')$$, 'saving twice is idempotent');
select is((select count(*)::integer from public.engineer_collection_entries), 1, 'duplicate save creates one entry');
select throws_ok($$select public.engineer_collection_change('save', null, null, 'profile', '00000000-0000-4000-8000-000000000001')$$, '42501', null, 'unavailable private records cannot be saved');
select lives_ok($$insert into engineer_test_values values('request', public.engineer_request_save(null,null,'Villa materials','Finish schedule',null,'[{"name":"Cornice","category_code":"cornices","quantity":20,"unit":"meter"}]','Cairo',array['9c000000-cccc-4ccc-8ccc-000000000001'::uuid])::text)$$, 'unverified professional claim can save a personal request');
select is((select public.engineer_request_context_read(value::uuid)->>'location' from engineer_test_values where name='request'), 'Cairo', 'owner can recover project location');
select is((select requester_audience from public.purchase_requests where id=(select value::uuid from engineer_test_values where name='request')), 'engineer', 'request uses server-derived audience');
select throws_ok($$select public.engineer_request_save((select value::uuid from engineer_test_values where name='request'),99,'Stale draft',null,null,'[]','', '{}')$$, 'VC001', null, 'stale revisions fail without gateway retry loops');
insert into engineer_test_values select 'image', public.purchase_request_image_request_upload(id, 'image/png') from public.purchase_request_items where request_id=(select value::uuid from engineer_test_values where name='request');
select lives_ok($$select public.media_upload_abandon('request', (select value from engineer_test_values where name='image'))$$, 'failed image reservation can be released');
select lives_ok($$select public.media_upload_abandon('request', (select value from engineer_test_values where name='image'))$$, 'upload abort is idempotent');
select lives_ok($$select public.purchase_request_publish((select value::uuid from engineer_test_values where name='request'),1)$$, 'engineer can publish');
set local request.jwt.claims = '{"sub":"70000001-0000-4000-8000-000000000001","role":"authenticated"}';
select is((select count(*)::integer from public.engineer_collections), 0, 'other caller sees no private collections');
select is((select count(*)::integer from public.engineer_collection_entries), 0, 'other caller sees no private entries');
select is((select public.engineer_request_context_read(value::uuid)->>'location' from engineer_test_values where name='request'), '', 'other caller cannot read private targeting');
select is((select public.engineer_request_location(value::uuid,'9c000000-cccc-4ccc-8ccc-000000000001') from engineer_test_values where name='request'), 'Cairo', 'selected showroom receives project location');
reset role;
select ok((select app.request_visible_to(value::uuid,'9c000000-cccc-4ccc-8ccc-000000000001','showroom_dealer') from engineer_test_values where name='request'), 'targeted showroom can discover request');
select ok(not (select app.request_visible_to(value::uuid,'91000005-1111-4111-8111-000000000005','showroom_dealer') from engineer_test_values where name='request'), 'untargeted showroom cannot discover request');
select ok(not (select app.request_visible_to(value::uuid,null,'showroom_dealer') from engineer_test_values where name='request'), 'null workspace cannot bypass targeting');
set local role authenticated;
select throws_ok($$select public.engineer_collection_change('delete_team',(select value::uuid from engineer_test_values where name='team'))$$, '42501', null, 'other persona cannot delete engineer team');
set local request.jwt.claims = '{"sub":"70000010-0000-4000-8000-000000000010","role":"authenticated"}';
select lives_ok($$select public.engineer_collection_change('delete_team',(select value::uuid from engineer_test_values where name='team'))$$, 'owner can delete a team');
reset role;
update public.users set status='suspended' where id='70000010-0000-4000-8000-000000000010';
set local role authenticated;
select throws_ok($$select public.engineer_collection_change('create_team',null,'Blocked')$$,'42501',null,'suspended engineer cannot mutate');
select * from finish();
rollback;
